WITH scored AS (SELECT *, AVG(amount) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS amount_avg_3_prior, AVG(amount) OVER (PARTITION BY merchant ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS amount_avg_2 FROM transactions WHERE amount BETWEEN 2000 AND 2800) SELECT s.id, s.account_id, s.txn_type, s.amount, s.txn_time, s.merchant, s.amount_avg_2, (SELECT SUM(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS sum_transaction_amount FROM scored s ORDER BY account_id DESC NULLS LAST
